using Innovia.Api.Common.Database; using Innovia.Api.Common.Database.Entities; using Microsoft.AspNetCore.Identity; using Microsoft.EntityFrameworkCore;
namespace Innovia.Api.Features.Users.DeleteUser;
public static class Endpoint { public static void Map(IEndpointRouteBuilder app)=>app.MapDelete("/{id:guid}",async(Guid id,UserManager<ApplicationUser> um,AppDbContext db,HttpContext http,CancellationToken ct)=>{var u=await um.FindByIdAsync(id.ToString());if(u is null)return Results.NotFound();if(Guid.TryParse(um.GetUserId(http.User),out var current)&&current==id)return Results.BadRequest("You cannot delete yourself.");var now=DateTimeOffset.UtcNow;await using var tx=await db.Database.BeginTransactionAsync(ct);var bs=await db.Bookings.Where(b=>b.UserId==id).ToListAsync(ct);foreach(var b in bs){b.UserNameSnapshot=$"{u.FirstName} {u.LastName}".Trim();b.UserEmailSnapshot=u.Email??"Unknown";b.UserDeleted=true;if(b.CancelledAt is null&&b.EndsAt>now)b.CancelledAt=now;}var result=await um.DeleteAsync(u);if(!result.Succeeded)return Results.BadRequest(result.Errors.Select(e=>e.Description));await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return Results.Ok(new{userId=id,cancelledBookingCount=bs.Count(b=>b.CancelledAt==now),preservedBookingCount=bs.Count});});}
